def compute(vars):
    old_rate = vars["v1"]
    new_rate = vars["v2"]
    decrease = old_rate - new_rate
    return {
        "value": decrease,
        "trace": {
            "old_rate": old_rate,
            "new_rate": new_rate,
            "decrease": decrease,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
